<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$type=$_GET['type']??'revenue';$currency=$_GET['currency']??null;$where=$currency?' AND i.currency=?':'';$params=$currency?[$currency]:[];function rows(PDO $db,string $sql,array $p=[]):array{$s=$db->prepare($sql);$s->execute($p);return $s->fetchAll(PDO::FETCH_ASSOC);}function money($v):string{return number_format((float)$v,2);}switch($type){case 'pipeline':$data=rows($db,"SELECT status,COUNT(*) leads,COALESCE(SUM(estimated_value),0) value FROM leads GROUP BY status ORDER BY FIELD(status,'new','contacted','proposal','won','lost')");break;case 'revenue':$data=rows($db,"SELECT DATE_FORMAT(i.issue_date,'%Y-%m') period,COUNT(*) invoices,COALESCE(SUM(i.total),0) invoiced,COALESCE(SUM(i.amount_paid),0) paid,COALESCE(SUM(i.balance_due),0) outstanding FROM invoices i WHERE i.status<>'cancelled' $where GROUP BY DATE_FORMAT(i.issue_date,'%Y-%m') ORDER BY period DESC LIMIT 24",$params);break;case 'payments':$data=rows($db,"SELECT p.gateway,p.status,COUNT(*) transactions,COALESCE(SUM(p.amount),0) amount FROM invoice_payments p GROUP BY p.gateway,p.status ORDER BY amount DESC");break;case 'clients':$data=rows($db,"SELECT c.id,c.name,c.company,COALESCE(SUM(i.total),0) invoiced,COALESCE(SUM(i.amount_paid),0) paid,COALESCE(SUM(i.balance_due),0) outstanding,COUNT(DISTINCT cp.id) projects FROM clients c LEFT JOIN invoices i ON i.client_id=c.id AND i.status<>'cancelled' LEFT JOIN client_projects cp ON cp.client_id=c.id GROUP BY c.id,c.name,c.company ORDER BY paid DESC");break;case 'projects':$data=rows($db,"SELECT p.id,p.project_number,p.name,p.status,p.budget,p.amount_paid,p.balance_due,COALESCE(c.cost,0) costs,COALESCE(t.labour_cost,0) labour_cost,(COALESCE(p.budget,0)-COALESCE(c.cost,0)-COALESCE(t.labour_cost,0)) forecast_margin FROM client_projects p LEFT JOIN (SELECT project_id,SUM(amount) cost FROM project_costs GROUP BY project_id)c ON c.project_id=p.id LEFT JOIN (SELECT x.project_id,SUM(x.hours*s.hourly_rate) labour_cost FROM project_time_entries x JOIN staff_members s ON s.id=x.staff_id GROUP BY x.project_id)t ON t.project_id=p.id ORDER BY p.due_date IS NULL,p.due_date");break;case 'team':$data=rows($db,"SELECT s.id,CONCAT(s.first_name,' ',s.last_name) staff,COUNT(DISTINCT t.id) tasks,COALESCE(SUM(te.hours),0) hours,COALESCE(SUM(te.hours*s.hourly_rate),0) labour_cost,COALESCE(SUM(CASE WHEN t.status='completed' THEN 1 ELSE 0 END),0) completed_tasks FROM staff_members s LEFT JOIN project_tasks t ON t.assigned_to=s.id LEFT JOIN project_time_entries te ON te.staff_id=s.id WHERE s.employment_status='active' GROUP BY s.id,staff ORDER BY hours DESC");break;case 'support':$data=rows($db,"SELECT status,priority,COUNT(*) total FROM support_tickets GROUP BY status,priority ORDER BY total DESC");break;default:$data=[];}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phase 14 BI Reports</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container-fluid p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">BI & Reporting Center</h1><a class="btn btn-outline-secondary" href="bi-dashboard.php">Executive Dashboard</a></div><div class="btn-group flex-wrap mb-3"><a class="btn btn-outline-primary" href="?type=revenue">Revenue</a><a class="btn btn-outline-primary" href="?type=payments">Payments</a><a class="btn btn-outline-primary" href="?type=pipeline">Sales Pipeline</a><a class="btn btn-outline-primary" href="?type=clients">Client Profitability</a><a class="btn btn-outline-primary" href="?type=projects">Projects</a><a class="btn btn-outline-primary" href="?type=team">Team</a><a class="btn btn-outline-primary" href="?type=support">Support</a></div><div class="card"><div class="card-body table-responsive"><table class="table table-sm table-striped"><thead><tr><?php if($data):foreach(array_keys($data[0]) as $h):?><th><?=htmlspecialchars((string)$h)?></th><?php endforeach;endif;?></tr></thead><tbody><?php foreach($data as $r):?><tr><?php foreach($r as $h=>$v):?><td><?=htmlspecialchars(in_array($h,['value','invoiced','paid','outstanding','amount','budget','amount_paid','balance_due','costs','labour_cost','forecast_margin'])?money($v):(string)$v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table><?php if(!$data):?><div class="text-muted">No report data available.</div><?php endif;?></div></div></main></body></html>